import{_ as c,C as o,c as d,o as s,aa as r,G as t}from"./chunks/framework.Cn7WEiMX.js";const b=JSON.parse('{"title":"SkullRenderer 类","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/developers/classes/skullrenderer-class.md","filePath":"wiki/Dynmap/developers/classes/skullrenderer-class.md"}'),i={name:"wiki/Dynmap/developers/classes/skullrenderer-class.md"};function n(p,e,u,h,k,m){const a=o("NolebaseGitContributors"),l=o("NolebaseGitChangelog");return s(),d("div",null,[e[0]||(e[0]=r('<h1 id="skullrenderer-类" tabindex="-1">SkullRenderer 类 <a class="header-anchor" href="#skullrenderer-类" aria-label="Permalink to &quot;SkullRenderer 类&quot;">​</a></h1> <p>SkullRenderer 类用于渲染头颅。着色器会在头部（<code>Rot</code>）使用 TileEntity 字段，选择渲染头颅类型（<code>SkullType</code>）。每个头颅都需要六个纹理——均从 <code>SKIN</code> 类型的纹理文件（包含人形实体完整纹理的文件）读取。皮肤必须使用正确的 <code>texturefile</code> 参数在<a href="./../../mod-support/texture-definition-files">纹理定义文件</a>中载入——如下为僵尸头颅的示例配置：</p> <div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  texturefile:id=zombie,filename=mob/zombie.png,format=SKIN</span></span></code></pre></div><p><code>block</code> 记录会与使用 SkullRenderer，且需要为每个 <code>SkullType</code> 定义值提供六面纹理引用的自定义方块绑定：首个序号（0）中的 <code>patch0</code> 到 <code>patch5</code>，第二个序号（1）中的 <code>patch6</code> 到 <code>patch11</code>，依此类推。</p> <h2 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h2> <p>无</p> <h2 id="需要纹理的补丁" tabindex="-1">需要纹理的补丁 <a class="header-anchor" href="#需要纹理的补丁" aria-label="Permalink to &quot;需要纹理的补丁&quot;">​</a></h2> <p>对于每个 <code>SkullType</code> 的值，从 <code>数字</code>=0 逐渐累加到 <code>数字</code>=最大值：</p> <ul><li><code>patch&lt;6 x 数字&gt;</code> - 头颅底部（在 <code>SKIN</code> 纹理中为序号 5）</li> <li><code>patch&lt;6 x 数字 + 1&gt;</code> - 头颅顶部（在 <code>SKIN</code> 纹理中为序号 4）</li> <li><code>patch&lt;6 x 数字 + 2&gt;</code> - 头颅背部（在 <code>SKIN</code> 纹理中为序号 1）</li> <li><code>patch&lt;6 x 数字 + 3&gt;</code> - 头颅正面（在 <code>SKIN</code> 纹理中为序号 0）</li> <li><code>patch&lt;6 x 数字 + 4&gt;</code> - 头颅侧面（在 <code>SKIN</code> 纹理中为序号 2）</li> <li><code>patch&lt;6 x 数字 + 5&gt;</code> - 头颅侧面（在 <code>SKIN</code> 纹理中为序号 3）</li></ul> ',17)),t(a),t(l)])}const S=c(i,[["render",n]]);export{b as __pageData,S as default};
